insert into public.content_exercises (id, grp, name, muscle, equip, simple, tip, note, lift, unit, sort) values
  ('ARC-082', 'Glúteo y cadera', 'Hip thrust con peso corporal', 'Glúteo mayor', 'Banco', 'Con la espalda alta apoyada en un banco y los pies en el suelo, subes la cadera apretando glúteo hasta quedar recta y bajas despacio.', 'Perfecto para aprender el movimiento o para hacer en casa. Mira al frente, no al techo, y aguanta un segundo arriba.', '', '', '', 82),
  ('ARC-083', 'Abdomen', 'Escaladores', 'Core, abdomen, hombro', 'Peso corporal', 'En plancha alta, llevas una rodilla hacia el pecho y la devuelves, alternando las piernas.', 'Hombros encima de las manos y cadera baja. Despacio trabaja el core; rápido se convierte en cardio.', '', '', '', 83),
  ('ARC-084', 'Pecho', 'Flexiones de rodillas', 'Pectoral, tríceps, hombro anterior', 'Peso corporal', 'Como una flexión normal, pero con las rodillas apoyadas en el suelo: bajas el pecho hasta casi tocar y empujas.', 'Cuerpo recto de rodillas a cabeza, sin sacar el culo. Es el paso previo para llegar a las flexiones completas.', '', '', '', 84),
  ('ARC-085', 'Pecho', 'Flexiones inclinadas en banco', 'Pectoral, tríceps, hombro anterior', 'Banco', 'Con las manos en un banco y el cuerpo recto, bajas el pecho hacia el borde y empujas hasta estirar los brazos.', 'Cuanto más alto el apoyo, más fácil. Codos a unos 45 grados del cuerpo, no abiertos en cruz.', '', '', '', 85)
